CREATE TABLE IF NOT EXISTS mera_owner_identities(user_id TEXT PRIMARY KEY REFERENCES users(id),email TEXT UNIQUE NOT NULL CHECK(email=lower(email)),verification_mode TEXT,verified_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS mera_identity_challenges(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),token_hash TEXT UNIQUE NOT NULL,expires_at TIMESTAMPTZ NOT NULL,consumed_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
